 drawDecor(){this.decorNodes.forEach(n=>n.destroy());this.decorNodes=[];this.decor.forEach(d=>{const c=this.furniture(d.name,d.x,d.y,d.color);if(d.name==='러그')c.setDepth(1);this.hotspot(c,5,-12,80,75,d.name+' · 옮기거나 보관하기',()=>this.interact({x:d.x,y:d.y},()=>{if(this.mode==='decorate')emit('decor-select',d);else{this.tweens.add({targets:c,angle:3,duration:100,yoyo:true});emit('thought',d.name==='작은 별 조명'?'작은 별이 반짝이네.':'여기에 두니까 잘 어울리네.')}}));this.decorNodes.push(c)})}
 validPlacement(c:{x:number;y:number}){return c.x>=0&&c.x<=16&&c.y>=0&&c.y<=14&&!this.blocked.has(`${c.x},${c.y}`)&&!(this.player.cell.x===c.x&&this.player.cell.y===c.y)&&!(this.guest&&this.guest.cell.x===c.x&&this.guest.cell.y===c.y)}
 placeAt(c:{x:number;y:number}){if(!this.validPlacement(c)){emit('thought','거기엔 못 놓겠어.');return}const blocks=new Set(this.blocked);blocks.add(`${c.x},${c.y}`);for(const target of [{x:1,y:1},{x:1,y:5},{x:4,y:1},{x:5,y:10},{x:4,y:5}]){if(!route(this.player.cell,target,blocks,true)){emit('thought','거기 두면 길이 막히겠어.');return}}const item={...this.placing,x:c.x,y:c.y,id:this.placing.id??Date.now()};const token=this.placementGate.begin();this.placing=null;this.ghost?.destroy();this.ghost=null;const started=this.walk(this.player,c,()=>{if(!this.placementGate.complete(token))return;this.particles(pos(c.x,c.y).x,pos(c.x,c.y).y);emit('placed',item);emit('guide',{id:'placed',text:'다시 누르면 옮길 수 있겠다.',fallback:'여기 두자.'})},true);if(!started){this.placementGate.cancel();emit('placement-cancelled')}}
